/* Native section surface and typography */
&.fdp-b-private-parties{padding:clamp(28px,5vw,76px) clamp(18px,5vw,72px);background:#f6f1e6;color:#28221f;font-family:Georgia,serif;} &.fdp-b-private-parties h2{color:#28221f;line-height:1.06;letter-spacing:-.025em;font-size:clamp(32px,4.4vw,62px);} &.fdp-b-private-parties h3{color:#28221f;font-family:Georgia,serif;font-size:clamp(21px,2.1vw,30px);line-height:1.15;margin:0 0 14px;} &.fdp-b-private-parties p{color:#28221f;line-height:1.7;} &.fdp-b-private-parties .fdp-content{max-width:1160px;margin:24px auto 0;} &.fdp-b-private-parties .fdp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;} &.fdp-b-private-parties .fdp-card{padding:clamp(22px,3vw,40px);background:#fffdf7;border:1px solid #b7a896;} &.fdp-b-private-parties .fdp-card p{margin-bottom:0;} &.fdp-b-private-parties .fdp-kicker{font-family:Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px;} &.fdp-b-private-parties .fdp-action{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:48px;padding:14px 24px;background:#713d35;color:#fffaf1;font:700 13px/1.3 Arial,sans-serif;letter-spacing:.06em;text-decoration:none;} &.fdp-b-private-parties .fdp-action:focus-visible{outline:3px solid #28221f;outline-offset:4px;} &.fdp-b-private-parties .fdp-action:hover{text-decoration:underline;} &.fdp-b-private-parties .fdp-actions{margin:28px 0 0;} &.fdp-b-private-parties .fdp-number{display:block;color:#713d35;font:700 13px/1.2 Arial,sans-serif;letter-spacing:.15em;margin-bottom:20px;} &.fdp-b-private-parties .fdp-list{margin:0;padding:0;list-style:none;} &.fdp-b-private-parties .fdp-list li{padding:16px 0;border-bottom:1px solid #b7a896;line-height:1.6;} @media(max-width:720px){&.fdp-b-private-parties .fdp-grid{grid-template-columns:1fr;} &.fdp-b-private-parties .fdp-card{padding:24px;} &.fdp-b-private-parties .fdp-action{width:100%;box-sizing:border-box;}} &.fdp-b-private-parties .fdp-editorial{display:grid;grid-template-columns:1.4fr 1fr;gap:clamp(30px,6vw,80px);}&.fdp-b-private-parties .fdp-editorial-lead>p:not(.fdp-kicker){font-size:18px;}&.fdp-b-private-parties .fdp-editorial-aside{border-left:1px solid #b7a896;padding-left:clamp(24px,4vw,50px);}&.fdp-b-private-parties .fdp-editorial-aside article{padding:20px 0;border-bottom:1px solid #b7a896;}&.fdp-b-private-parties .fdp-editorial-aside h3{font-style:italic;font-size:27px;}&.fdp-b-private-parties .fdp-editorial-aside article:last-child{border-bottom:0;}@media(max-width:720px){&.fdp-b-private-parties .fdp-editorial{grid-template-columns:1fr;}&.fdp-b-private-parties .fdp-editorial-aside{border-left:0;border-top:1px solid #b7a896;padding-left:0;padding-top:24px;}}
/* Keep content within the section on narrow screens */
&.fdp-b-private-parties,&.fdp-b-private-parties *{box-sizing:border-box;}&.fdp-b-private-parties .fdp-content,&.fdp-b-private-parties .fdp-content>*,&.fdp-b-private-parties .fdp-content article,&.fdp-b-private-parties .fdp-content aside{min-width:0;}&.fdp-b-private-parties p,&.fdp-b-private-parties li,&.fdp-b-private-parties a{overflow-wrap:break-word;}
/* Preserve native editorial contrast and respond to section width */
&.fdp-b-private-parties{background:#f6f1e6!important;color:#28221f!important;container-type:inline-size;} &.fdp-b-private-parties h2,&.fdp-b-private-parties .text-body1{color:#28221f!important;} @container(max-width:720px){&.fdp-b-private-parties .fdp-editorial{grid-template-columns:1fr;} &.fdp-b-private-parties .fdp-editorial-aside{border-left:0;border-top:1px solid #b7a896;padding-left:0;padding-top:24px;} &.fdp-b-private-parties .fdp-action{width:100%;}}
